WITH product_summary AS (SELECT product_id, MAX(quantity) - MIN(quantity) AS quantity_range, COUNT(DISTINCT quantity) AS unique_products FROM order_items WHERE order_id IN (8, 12, 18, 38) GROUP BY product_id) SELECT p.id, p.price, ps.quantity_range, ps.unique_products FROM products p LEFT JOIN product_summary ps ON p.id = ps.product_id WHERE ps.unique_products > 3 ORDER BY quantity_range;
